label("$C$", (4, 0), SE);
label("$D$", (0, 0), SW);
[/asy]

question:
도형에서, $\triangle ABC$는 이등변삼각형이고 넓이는 240이다. $A$의 $y$-좌표는 얼마인가?

[asy]

import olympiad;

// Draw and label axes

draw((0, -3)--(0, 30), Arrow);

draw((-3, 0)--(30, 0), Arrow);

label("$y$", (0, 30), N);

label("$x$", (30, 0), E);

// Draw triangle

pair a = (10, 24); pair b = (0, 0); pair c = (20, 0);

draw(a--b--c--cycle);

dot(a); dot(b); dot(c);

// Label points

label("$A$", a, N);

label("$B(0, 0)$", b, NW);

label("$C(20, 0)$", c, S);

// Tick marks

add(pathticks(a--b, s=45));

add(pathticks(a--c, s=45));

[/asy]

